// D:\Healthyme pro\frontend\src\components\Dashboard.js
import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import AppShell from './AppShell';
import { getHistory } from '../services/api';

const DAILY_WATER_INCREMENT = 0.25;
const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

function clampScore(value) {
  const numeric = Number(value);
  if (Number.isNaN(numeric)) {
    return 0;
  }
  return Math.max(0, Math.min(100, numeric));
}

function getDateKey(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).toISOString().slice(0, 10);
}

function getActiveDateSet(history) {
  return new Set(
    history.map((item) => {
      const date = new Date(item.created_at);
      return getDateKey(date);
    })
  );
}

function getCurrentStreak(activeDates) {
  let streak = 0;
  const cursor = new Date();

  while (activeDates.has(getDateKey(cursor))) {
    streak += 1;
    cursor.setDate(cursor.getDate() - 1);
  }

  return streak;
}

function getMonthStats(history, monthDate) {
  const month = monthDate.getMonth();
  const year = monthDate.getFullYear();
  const items = history.filter((item) => {
    const created = new Date(item.created_at);
    return created.getMonth() === month && created.getFullYear() === year;
  });

  const activeDays = new Set(items.map((item) => getDateKey(new Date(item.created_at)))).size;

  return {
    count: items.length,
    activeDays,
  };
}

function getCalendarCells(monthDate, activeDates) {
  const year = monthDate.getFullYear();
  const month = monthDate.getMonth();
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const firstWeekday = (firstDay.getDay() + 6) % 7;
  const daysInMonth = lastDay.getDate();
  const cells = [];

  for (let index = 0; index < firstWeekday; index += 1) {
    cells.push({ type: 'empty', key: `empty-start-${index}` });
  }

  for (let day = 1; day <= daysInMonth; day += 1) {
    const date = new Date(year, month, day);
    const key = getDateKey(date);
    const todayKey = getDateKey(new Date());
    cells.push({
      type: 'day',
      key,
      day,
      active: activeDates.has(key),
      isToday: key === todayKey,
    });
  }

  while (cells.length % 7 !== 0) {
    cells.push({ type: 'empty', key: `empty-end-${cells.length}` });
  }

  return cells;
}

function splitFoodNotes(foodNotes) {
  return String(foodNotes || '')
    .split(/,|\band\b|\n/i)
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function buildMealCards(foodPreference, foodNotes) {
  const notes = String(foodNotes || '').toLowerCase();
  const parts = splitFoodNotes(foodNotes);

  if (notes.includes('dosa') || notes.includes('idli')) {
    return [
      { label: 'Breakfast', value: 'Dosa or idli with sambar', accent: 'orange', note: 'Matches your South-style breakfast pattern.' },
      { label: 'Lunch', value: 'Dal rice with vegetables', accent: 'teal', note: 'Keeps your lunch close to what you already eat.' },
      { label: 'Dinner', value: 'Roti curry with lighter portions', accent: 'purple', note: 'Balances your evening meal for recovery.' },
    ];
  }

  if (parts.length >= 3) {
    return [
      { label: 'Breakfast', value: parts[0], accent: 'orange', note: 'Picked directly from your food notes.' },
      { label: 'Lunch', value: parts[1], accent: 'teal', note: 'Picked directly from your food notes.' },
      { label: 'Dinner', value: parts[2], accent: 'purple', note: 'Picked directly from your food notes.' },
    ];
  }

  const templateMap = {
    'High Protein': [
      { label: 'Breakfast', value: 'Paneer or eggs with oats', accent: 'orange', note: 'Protein-heavy start for muscle support.' },
      { label: 'Lunch', value: 'Dal rice with curd and salad', accent: 'teal', note: 'Steadier midday energy and better satiety.' },
      { label: 'Dinner', value: 'Roti with tofu or paneer curry', accent: 'purple', note: 'Supports recovery without overloading calories.' },
    ],
    Vegetarian: [
      { label: 'Breakfast', value: 'Poha or upma with fruit', accent: 'orange', note: 'Easy vegetarian morning meal.' },
      { label: 'Lunch', value: 'Dal, rice, sabzi, and curd', accent: 'teal', note: 'Balanced vegetarian lunch.' },
      { label: 'Dinner', value: 'Roti with sabzi and sprouts', accent: 'purple', note: 'Lighter dinner with added fiber.' },
    ],
    'South Indian': [
      { label: 'Breakfast', value: 'Idli, dosa, or uthappam', accent: 'orange', note: 'Built around your preferred cuisine.' },
      { label: 'Lunch', value: 'Rice, rasam, dal, and poriyal', accent: 'teal', note: 'Classic balanced South Indian lunch.' },
      { label: 'Dinner', value: 'Dosa with chutney and soup', accent: 'purple', note: 'A lighter evening variation.' },
    ],
  };

  return templateMap[foodPreference] || [
    { label: 'Breakfast', value: 'Protein-rich breakfast', accent: 'orange', note: 'Starter meal when no detailed food notes are present.' },
    { label: 'Lunch', value: 'Balanced lunch plate', accent: 'teal', note: 'Keeps carbs, protein, and fiber together.' },
    { label: 'Dinner', value: 'Light recovery dinner', accent: 'purple', note: 'Ends the day with simpler portions.' },
  ];
}

function buildAdaptiveMealPlan(foodPreference, foodNotes, goal) {
  const notes = String(foodNotes || '').toLowerCase();
  const isWeightLoss = goal === 'Lose Weight';
  const isMuscle = goal === 'Gain Muscle';

  const basePlan = [
    {
      meal: 'Breakfast',
      title: notes.includes('dosa') || notes.includes('idli') ? '2 dosa or 3 idli + sambar' : 'Oats or poha with fruit',
      support: isMuscle ? 'Add paneer, eggs, or milk for extra protein.' : 'Keep portions moderate and avoid heavy fried add-ons.',
      accent: 'orange',
    },
    {
      meal: 'Lunch',
      title: notes.includes('dal') && notes.includes('rice') ? 'Dal rice + sabzi + curd' : 'Rice or roti + dal + vegetables',
      support: isWeightLoss ? 'Use more vegetables and slightly reduce rice quantity.' : 'Keep a balanced mix of carbs and protein.',
      accent: 'teal',
    },
    {
      meal: 'Snack',
      title: isMuscle ? 'Fruit + nuts + curd or buttermilk' : 'Fruit + sprouts or buttermilk',
      support: 'Prevents low-energy hunger and keeps food timing consistent.',
      accent: 'blue',
    },
    {
      meal: 'Dinner',
      title: notes.includes('roti') ? 'Roti + curry + salad' : 'Light roti/rice + curry',
      support: isWeightLoss ? 'Keep dinner lighter than lunch.' : 'Add one protein side for better recovery.',
      accent: 'purple',
    },
  ];

  if (foodPreference === 'High Protein') {
    basePlan[0].title = 'Eggs or paneer + oats or dosa';
    basePlan[1].title = 'Dal rice + paneer/chicken + salad';
    basePlan[3].title = 'Roti + paneer/tofu curry';
  }

  return basePlan;
}

export default function Dashboard() {
  const navigate = useNavigate();
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [todayWater, setTodayWater] = useState(() => Number(localStorage.getItem('healthyme_today_water') || 0));
  const [calendarMonth, setCalendarMonth] = useState(() => {
    const now = new Date();
    return new Date(now.getFullYear(), now.getMonth(), 1);
  });

  const storedUser = localStorage.getItem('user');
  const user = storedUser ? JSON.parse(storedUser) : null;
  const profile = user?.profile || {};

  useEffect(() => {
    localStorage.setItem('healthyme_today_water', String(todayWater));
  }, [todayWater]);

  useEffect(() => {
    let isMounted = true;

    const fetchHistory = async () => {
      setLoading(true);
      setError('');
      try {
        const response = await getHistory();
        if (isMounted) {
          setHistory(Array.isArray(response) ? response : []);
        }
      } catch (fetchError) {
        if (fetchError.message === 'Missing authentication token') {
          navigate('/login');
          return;
        }
        if (isMounted) {
          setError(fetchError.message || 'Failed to fetch data');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    fetchHistory();
    return () => {
      isMounted = false;
    };
  }, [navigate]);

  const activeDates = useMemo(() => getActiveDateSet(history), [history]);
  const streakCount = useMemo(() => getCurrentStreak(activeDates), [activeDates]);
  const monthStats = useMemo(() => getMonthStats(history, calendarMonth), [history, calendarMonth]);
  const calendarCells = useMemo(() => getCalendarCells(calendarMonth, activeDates), [calendarMonth, activeDates]);

  const summary = useMemo(() => {
    const latest = history[0];
    const average = (key) =>
      history.length
        ? history.reduce((sum, item) => sum + Number(item.input_data?.[key] || 0), 0) / history.length
        : 0;

    const weeklyEntries = history.filter((item) => {
      const created = new Date(item.created_at);
      return Date.now() - created.getTime() <= 7 * 24 * 60 * 60 * 1000;
    });

    const latestScore = latest ? clampScore(latest.score) : null;
    const waterGoal = Number(profile.daily_water_goal || 3);
    const averageCalories = average('calories');

    return {
      latestScore,
      latestScoreLabel: latestScore === null ? '--' : latestScore.toFixed(1),
      averageSleepLabel: average('sleep') ? `${average('sleep').toFixed(1)}h` : '0h',
      averageWaterLabel: average('water') ? `${average('water').toFixed(1)}L` : '0L',
      averageCaloriesLabel: averageCalories ? `${Math.round(averageCalories)}` : '0',
      averageCalories,
      weeklyPredictionCount: weeklyEntries.length,
      waterGoal,
      calorieGoal: profile.goal === 'Gain Muscle' ? 2600 : profile.goal === 'Lose Weight' ? 1900 : 2200,
    };
  }, [history, profile.daily_water_goal, profile.goal]);

  const weeklyChart = useMemo(() => {
    const recent = [...history]
      .slice(0, 7)
      .reverse()
      .map((item) => ({
        day: new Date(item.created_at).toLocaleDateString('en-US', { weekday: 'short' }),
        score: clampScore(item.score),
      }));

    return recent.length === 0 ? DAY_LABELS.map((day) => ({ day, score: 0 })) : recent;
  }, [history]);

  const mealCards = useMemo(
    () => buildMealCards(profile.food_preference, profile.food_notes),
    [profile.food_preference, profile.food_notes]
  );

  const adaptiveMealPlan = useMemo(
    () => buildAdaptiveMealPlan(profile.food_preference, profile.food_notes, profile.goal),
    [profile.food_preference, profile.food_notes, profile.goal]
  );

  const scoreMessage = useMemo(() => {
    if (summary.latestScore === null) {
      return 'Run your first prediction to unlock insights, meal guidance, and trend visuals.';
    }
    if (summary.latestScore >= 80) {
      return 'Excellent momentum. Keep sleep and hydration steady to protect your score.';
    }
    if (summary.latestScore >= 60) {
      return 'You are on track. A little more hydration and recovery can push you higher.';
    }
    if (summary.latestScore >= 40) {
      return 'Your routine can improve quickly with better rest, food balance, and water intake.';
    }
    return 'Start simple today: hydrate more, eat cleaner, and get better sleep tonight.';
  }, [summary.latestScore]);

  const waterProgress = Math.min(100, Math.round((todayWater / (summary.waterGoal || 1)) * 100));
  const calorieProgress = Math.min(100, Math.round((summary.averageCalories / (summary.calorieGoal || 1)) * 100));
  const gaugeValue = summary.latestScore === null ? 0 : Math.round(summary.latestScore);

  const addWater = () => {
    setTodayWater((current) => Number((current + DAILY_WATER_INCREMENT).toFixed(2)));
  };

  const resetWater = () => {
    setTodayWater(0);
  };

  const openPreviousMonth = () => {
    setCalendarMonth((current) => new Date(current.getFullYear(), current.getMonth() - 1, 1));
  };

  const openNextMonth = () => {
    setCalendarMonth((current) => new Date(current.getFullYear(), current.getMonth() + 1, 1));
  };

  return (
    <AppShell
      title={`Welcome back, ${user?.name || 'User'}`}
      subtitle="A wider premium dashboard with dynamic meal planning, full-month streak tracking, hydration progress, and ML score insights."
      actions={<button type="button" className="ghost-btn" onClick={() => navigate('/predict')}>New prediction</button>}
    >
      {loading ? <div className="empty-state">Loading...</div> : null}
      {!loading && error ? <div className="empty-state">{error || 'Failed to fetch data'}</div> : null}

      {!loading && !error ? (
        <>
          <section className="dashboard-hero premium-dark expanded-hero">
            <div className="hero-score-panel premium-dark-panel">
              <span className="floating-blob blob-one" />
              <span className="floating-blob blob-two" />
              <div className="hero-illustration">AI</div>

              <div className="eyebrow">AI wellness score</div>
              <div className="hero-score-row">
                <div>
                  <h2>{summary.latestScoreLabel}</h2>
                  <p>{scoreMessage}</p>
                </div>
                <div className="hero-badge-stack">
                  <span className="hero-badge">Goal: {profile.goal || 'Stay Fit'}</span>
                  <span className="hero-badge soft">Live streak: {streakCount} days</span>
                </div>
              </div>

              <div className="hero-score-footer">
                <span>{summary.weeklyPredictionCount} predictions this week</span>
                <div className="button-row">
                  <button type="button" className="ghost-btn ghost-invert compact" onClick={() => navigate('/history')}>
                    Open history
                  </button>
                  <button type="button" className="ghost-btn ghost-invert compact" onClick={() => navigate('/chat')}>
                    Ask coach
                  </button>
                </div>
              </div>
            </div>

            <div className="hero-side-grid expanded-side-grid">
              <div className="spotlight-card water glass-panel">
                <span className="eyebrow">Hydration target</span>
                <strong>{summary.waterGoal}L</strong>
                <p>{profile.food_preference || 'Balanced'} nutrition plan</p>
              </div>

              <div className="spotlight-card food glass-panel">
                <span className="eyebrow">Food profile</span>
                <strong>{profile.food_preference || 'Balanced'}</strong>
                <p>{profile.food_notes || 'Add food notes during registration for a more personalized dashboard.'}</p>
              </div>

              <div className="spotlight-card glass-panel monthly-spotlight">
                <span className="eyebrow">Monthly consistency</span>
                <strong>{monthStats.activeDays} active days</strong>
                <p>{monthStats.count} predictions in {calendarMonth.toLocaleDateString('en-US', { month: 'long' })}.</p>
              </div>
            </div>
          </section>

          <section className="wellness-grid expanded-wellness-grid">
            <div className="progress-card glass-panel">
              <div className="progress-ring" style={{ '--progress': `${waterProgress}%`, '--ring-color': '#20b8a6' }}>
                <div>
                  <strong>{waterProgress}%</strong>
                  <span>Water</span>
                </div>
              </div>
              <div className="progress-copy">
                <h3>Water intake tracker</h3>
                <p>{todayWater.toFixed(2)}L logged today out of your {summary.waterGoal}L hydration goal.</p>
                <div className="button-row">
                  <button type="button" className="primary-btn compact" onClick={addWater}>+ 250ml</button>
                  <button type="button" className="ghost-btn compact" onClick={resetWater}>Reset</button>
                </div>
              </div>
            </div>

            <div className="progress-card glass-panel">
              <div className="progress-ring" style={{ '--progress': `${calorieProgress}%`, '--ring-color': '#ff9533' }}>
                <div>
                  <strong>{calorieProgress}%</strong>
                  <span>Calories</span>
                </div>
              </div>
              <div className="progress-copy">
                <h3>Food consumption trend</h3>
                <p>Average calories: {summary.averageCaloriesLabel} / {summary.calorieGoal}. Goal tuned for {profile.goal || 'general fitness'}.</p>
                <span className="hint">Track a new day in Predict to refresh this insight.</span>
              </div>
            </div>

            <div className="progress-card glass-panel habit-card">
              <div className="habit-badge">HM</div>
              <div className="progress-copy">
                <h3>Habit momentum</h3>
                <p>{streakCount > 0 ? `You have logged ${streakCount} days in a row.` : 'Log today to start a new daily streak.'}</p>
                <div className="button-row">
                  <button type="button" className="ghost-btn compact" onClick={() => navigate('/predict')}>Log today</button>
                  <button type="button" className="ghost-btn compact" onClick={() => setCalendarMonth(new Date(new Date().getFullYear(), new Date().getMonth(), 1))}>This month</button>
                </div>
              </div>
            </div>
          </section>

          <section className="dashboard-grid luxury expanded-dashboard-grid">
            <div className="panel-card glass-panel gauge-panel">
              <div className="panel-head">
                <h3>Circular Score Gauge</h3>
                <span className="top-pill">Live score view</span>
              </div>
              <div className="gauge-layout">
                <div className="score-gauge" style={{ '--score-progress': gaugeValue }}>
                  <div className="score-gauge-inner">
                    <strong>{summary.latestScoreLabel}</strong>
                    <span>Health score</span>
                  </div>
                </div>
                <div className="gauge-copy">
                  <strong>
                    {gaugeValue >= 80 ? 'Excellent' : gaugeValue >= 60 ? 'Strong' : gaugeValue >= 40 ? 'Average' : 'Needs care'}
                  </strong>
                  <p>This gauge reflects your latest ML result from sleep, water, exercise, and calories.</p>
                </div>
              </div>
            </div>

            <div className="panel-card glass-panel">
              <div className="panel-head">
                <h3>Weekly Score Trend</h3>
                <span className="top-pill">Last 7 predictions</span>
              </div>
              <div className="weekly-chart">
                {weeklyChart.map((item, index) => (
                  <div className="chart-col" key={`${item.day}-${index}`}>
                    <div className="chart-track">
                      <div className="chart-bar" style={{ height: `${Math.max(item.score, 6)}%` }} />
                    </div>
                    <strong>{Math.round(item.score)}</strong>
                    <span>{item.day}</span>
                  </div>
                ))}
              </div>
            </div>
          </section>

          <section className="dashboard-grid luxury expanded-dashboard-grid">
            <div className="panel-card glass-panel bottle-panel">
              <div className="panel-head">
                <h3>Water Bottle Tracker</h3>
                <span className="top-pill">{todayWater.toFixed(2)}L today</span>
              </div>
              <div className="bottle-wrap">
                <div className="water-bottle">
                  <div className="water-bottle-cap" />
                  <div className="water-bottle-body">
                    <div className="water-fill" style={{ height: `${Math.max(waterProgress, 4)}%` }}>
                      <span className="water-wave" />
                    </div>
                  </div>
                </div>
                <div className="bottle-copy">
                  <strong>{waterProgress}% of goal</strong>
                  <p>Keep tapping +250ml to simulate a live hydration tracker like a health app.</p>
                </div>
              </div>
            </div>

            <div className="panel-card glass-panel month-calendar-panel">
              <div className="panel-head">
                <h3>Streak Calendar</h3>
                <div className="calendar-nav">
                  <button type="button" className="ghost-btn compact" onClick={openPreviousMonth}>Prev</button>
                  <span className="top-pill calendar-month-label">{calendarMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</span>
                  <button type="button" className="ghost-btn compact" onClick={openNextMonth}>Next</button>
                </div>
              </div>

              <div className="calendar-weekdays">
                {DAY_LABELS.map((day) => (
                  <span key={day}>{day}</span>
                ))}
              </div>

              <div className="month-calendar-grid">
                {calendarCells.map((cell) =>
                  cell.type === 'empty' ? (
                    <div key={cell.key} className="month-day empty" />
                  ) : (
                    <div key={cell.key} className={`month-day ${cell.active ? 'active' : ''} ${cell.isToday ? 'today' : ''}`}>
                      <span>{cell.day}</span>
                      <strong>{cell.active ? 'Done' : 'Free'}</strong>
                    </div>
                  )
                )}
              </div>
            </div>
          </section>

          <div className="stats-grid advanced expanded-stats-grid">
            <div className="stat-card glass-panel">
              <div className="card-icon icon-orange">SC</div>
              <p className="stat-value">{summary.latestScoreLabel}</p>
              <div className="stat-label">Latest score</div>
            </div>
            <div className="stat-card glass-panel">
              <div className="card-icon icon-teal">SL</div>
              <p className="stat-value">{summary.averageSleepLabel}</p>
              <div className="stat-label">Avg. sleep</div>
            </div>
            <div className="stat-card glass-panel">
              <div className="card-icon icon-blue">WA</div>
              <p className="stat-value">{summary.averageWaterLabel}</p>
              <div className="stat-label">Avg. water</div>
            </div>
            <div className="stat-card glass-panel">
              <div className="card-icon icon-purple">CA</div>
              <p className="stat-value">{summary.averageCaloriesLabel}</p>
              <div className="stat-label">Avg. calories</div>
            </div>
          </div>

          <section className="panel-card glass-panel meal-section">
            <div className="panel-head">
              <h3>Meal Cards</h3>
              <span className="top-pill">{profile.food_preference || 'Balanced'} plan</span>
            </div>
            <div className="meal-grid expanded-meal-grid">
              {mealCards.map((meal) => (
                <article key={meal.label} className={`meal-card ${meal.accent}`}>
                  <span className="meal-label">{meal.label}</span>
                  <strong>{meal.value}</strong>
                  <p>{meal.note}</p>
                  <button type="button" className="ghost-btn compact meal-btn" onClick={() => navigate('/predict')}>
                    Track this meal
                  </button>
                </article>
              ))}
            </div>
          </section>

          <section className="panel-card glass-panel adaptive-plan-section">
            <div className="panel-head">
              <h3>Adaptive Meal Plan</h3>
              <span className="top-pill">Updates from your food notes</span>
            </div>
            <div className="adaptive-plan-grid">
              {adaptiveMealPlan.map((item) => (
                <article key={item.meal} className={`adaptive-plan-card ${item.accent}`}>
                  <span className="meal-label">{item.meal}</span>
                  <strong>{item.title}</strong>
                  <p>{item.support}</p>
                  <div className="button-row">
                    <button type="button" className="ghost-btn compact" onClick={() => navigate('/predict')}>
                      Log meal
                    </button>
                    <button type="button" className="ghost-btn compact" onClick={() => navigate('/chat')}>
                      Ask coach
                    </button>
                  </div>
                </article>
              ))}
            </div>
          </section>

          <section className="dashboard-grid luxury expanded-dashboard-grid">
            <div className="panel-card feature-panel glass-panel">
              <div className="panel-head">
                <h3>Quick Actions</h3>
                <span className="top-pill">Personalized control center</span>
              </div>
              <div className="action-grid advanced">
                <button type="button" className="action-card premium" onClick={() => navigate('/predict')}>
                  <div className="card-icon icon-teal">PR</div>
                  <h3>Predict Score</h3>
                  <p>Run a fresh ML prediction from your sleep, water, exercise, and calories.</p>
                  <span className="card-arrow">Open</span>
                </button>
                <button type="button" className="action-card premium" onClick={() => navigate('/history')}>
                  <div className="card-icon icon-purple">HI</div>
                  <h3>View History</h3>
                  <p>See previous snapshots and compare patterns across your health routine.</p>
                  <span className="card-arrow">Open</span>
                </button>
                <button type="button" className="action-card premium" onClick={() => navigate('/chat')}>
                  <div className="card-icon icon-orange">AI</div>
                  <h3>Coach Chat</h3>
                  <p>Ask for daily advice about hydration, food, exercise, and better recovery.</p>
                  <span className="card-arrow">Open</span>
                </button>
              </div>
            </div>

            <div className="stack">
              <div className="panel-card insights-panel glass-panel">
                <div className="panel-head">
                  <h3>Daily Focus</h3>
                  <span className="top-pill">Smart suggestions</span>
                </div>
                <div className="insight-list">
                  <div className="insight-item">
                    <strong>Hydration</strong>
                    <span>{waterProgress < 100 ? 'Drink one more glass before evening.' : 'Great job hitting your water target.'}</span>
                  </div>
                  <div className="insight-item">
                    <strong>Sleep</strong>
                    <span>{summary.averageSleepLabel === '0h' ? 'Add your first prediction to unlock sleep insights.' : `Your recent average is ${summary.averageSleepLabel}.`}</span>
                  </div>
                  <div className="insight-item">
                    <strong>Nutrition</strong>
                    <span>{profile.food_preference || 'Balanced'} plan with {profile.goal || 'fitness'} as the main goal.</span>
                  </div>
                </div>
              </div>

              <div className="panel-card profile-panel glass-panel">
                <h3>Your Health Profile</h3>
                <div className="mini-grid">
                  <div className="mini-card"><span className="hint">Goal</span><strong>{profile.goal || 'Stay Fit'}</strong></div>
                  <div className="mini-card"><span className="hint">Activity</span><strong>{profile.activity_level || 'Moderate'}</strong></div>
                  <div className="mini-card"><span className="hint">Height</span><strong>{profile.height || '--'} cm</strong></div>
                  <div className="mini-card"><span className="hint">Weight</span><strong>{profile.weight || '--'} kg</strong></div>
                </div>
              </div>
            </div>
          </section>
        </>
      ) : null}
    </AppShell>
  );
}
